"""GR5398 Timing: complete Stage-2 Rule v1 + rolling GRU residual controller.

Single submission file: exposure(as_of, data) -> [0,1].
No run-time PyTorch, checkpoint files, direct disk access, network access, or random updates.
Optional point-in-time FinGPT data is obtained only through DataView.extra().

All offline parameters are generated by train_timing.py.
GRU checkpoint for year y was pretrained OFFLINE with 5-session labels entirely
observed by December 31 of y; the next calendar year may use that checkpoint.
The second-stage forecaster receives chronological out-of-time GRU features
for each training week, not a later checkpoint re-encoding earlier labels.
The GRU supplies forecasts of future daily-close-path downside/upside and return.
The small, regularized market forecaster is re-calibrated from *completed* QQQ
weekly windows every 4 weeks. This is a model-based/contextual-Q policy, NOT a
claim of experience with true course selected-stock portfolio rewards; rolling Q
utility targets are market-proxy estimates; direct Q uses selection NAV proxies and execution is only weekly.
"""
from __future__ import annotations
import math
from dataclasses import dataclass
import numpy as np
import pandas as pd

# Ablations: changing either toggle does not change the market data boundary.
ROLLING_Q = True            # False: 2017-only frozen forecast calibration
ROLLING_GRU = True          # True: use prior-year GRU supervised checkpoint
ENABLE_RL = True            # False: EXACT original Stage-2 Rule v1 target
ENABLE_REGIME_GATES = True
ENABLE_HYSTERESIS = True
RL_START = pd.Timestamp("2018-01-01")
UPDATE_EVERY_WEEKS = 4

# Values in *percent* of QQQ weekly returns/daily-close risk.
FORECAST_RIDGE = 24.0
FORECAST_ANCHOR_RIDGE = 15.0
FORECAST_HALF_LIFE_WEEKS = 104.0
FORECAST_ROLLING_BLEND = 0.70
REGIME_PRIOR_EQUIV_WEEKS = 16.0  # avoid over-reacting to rare-regime samples
# Conservative action utility for estimated return and intraweek risk.
Q_DOWNSIDE_AVERSION = 0.22
Q_UPSIDE_PARTICIPATION = 0.08
Q_TURNOVER_COST = 0.0006
Q_RESIDUAL_COST = 0.00065
