REBOUND_SCORE_SLOPE = 4.0
LONG_TREND_WEIGHT = 0.70
VIX_CALM_WEIGHT = 0.25
RISK_MULTIPLIER_FLOOR = 0.65

# Stage-2 defensive overlay, copied from the fixed-rule benchmark.
SHOCK_LOOKBACK_SESSIONS = 5
STRESS_QQQ_RETURN_5D = -0.06
STRESS_VIX_RELATIVE_RISE_5D = 0.20
PANIC_QQQ_RETURN_5D = -0.10
STRESS_EXPOSURE_CAP = 0.40
PANIC_EXPOSURE_CAP = 0.15
# Action trust-region limits are fixed research hypotheses, NOT fitted to VAL.
# The RL correction is within the Stage-2 safety cap at all times.
# Actions remain the original pre-VAL asymmetric research design. The first
# safety cap is provided by Rule v1, not learned by the agent.
# These options are *residuals relative to the Stage-2 target*.
