def _values(series, index, default):
    """Align history using backward-only carry-forward; never backfill futures."""
    if series is None:
        return pd.Series(default, index=index, dtype=float)
    if isinstance(series, pd.DataFrame):
        if series.shape[1] == 0:
            return pd.Series(default, index=index, dtype=float)
        series = series.iloc[:, 0]
    s = pd.to_numeric(series, errors="coerce").copy()
    s.index = pd.to_datetime(s.index)
    s = s[~s.index.duplicated(keep="last")].sort_index()
    return s.reindex(index, method="ffill").fillna(default).astype(float)


def _read_panel(data):
    # A single stock-price request; DataView itself enforces as_of cutoff.
    prices = data.close(["QQQ", "SPY"], lookback=3800)
    if prices is None or "QQQ" not in prices:
        return None
    prices = prices.copy()
    prices.index = pd.to_datetime(prices.index)
    prices = prices.sort_index()
    q = pd.to_numeric(prices["QQQ"], errors="coerce")
    q = q.replace([np.inf, -np.inf], np.nan)
    q = q[q > 0].dropna()
    if len(q) < 150:
        return None
    spy = _values(prices["SPY"] if "SPY" in prices else None, q.index, float(q.iloc[0]))
    vix = _values(data.market("^VIX"), q.index, 25.0)
    # Macro factors are lagged one trading observation to avoid assuming
    # same-day closing release availability. They are not GRU input factors.
    try:
        credit = _values(data.macro("BAA10Y"), q.index, 2.0).shift(1).fillna(2.0)
    except (KeyError, ValueError, AttributeError):
        credit = pd.Series(2.0, index=q.index)
    try:
        curve = _values(data.macro("T10Y2Y"), q.index, 1.0).shift(1).fillna(1.0)
    except (KeyError, ValueError, AttributeError):
        curve = pd.Series(1.0, index=q.index)
    return q, spy, vix, credit, curve


def _sequence_inputs(qqq, spy, vix):
    """Fixed feature scale shared by all annual GRU checkpoints."""
    ret1 = qqq.pct_change(fill_method=None).fillna(0.0)
    ret5 = (qqq / qqq.shift(5) - 1.0).fillna(0.0)
    spy5 = (spy / spy.shift(5) - 1.0).fillna(0.0)
    vol20 = (ret1.rolling(20).std() * math.sqrt(252)).fillna(0.0)
    vix5 = (vix / vix.shift(5) - 1.0).fillna(0.0)
    x = np.column_stack((ret1.to_numpy() / .025,
                         ret5.to_numpy() / .075,
                         spy5.to_numpy() / .060,
                         vol20.to_numpy() / .35,
                         vix.to_numpy() / 25.0 - 1.0,
                         vix5.to_numpy() / .35))
    return np.clip(np.nan_to_num(x, nan=0.0, posinf=3., neginf=-3.), -3., 3.), ret1, ret5, spy5, vol20, vix5


def _gru_forward_checkpoint(x_daily, week_pos, checkpoint):
    """Deterministic NumPy GRU forward for an explicitly eligible snapshot."""
    w_ih, w_hh, b_ih, b_hh, head_w, head_b = _GRU_BANK[int(checkpoint)]
    seq_idx = np.maximum(week_pos[:, None] - np.arange(19, -1, -1)[None, :], 0)
    xx = x_daily[seq_idx]
    h = np.zeros((len(week_pos), 8), dtype=np.float64)
    for step in range(20):
        gates_x = xx[:, step, :] @ w_ih.T + b_ih
        gates_h = h @ w_hh.T + b_hh
        r = 1. / (1. + np.exp(-np.clip(gates_x[:, :8] + gates_h[:, :8], -40., 40.)))
        z = 1. / (1. + np.exp(-np.clip(gates_x[:, 8:16] + gates_h[:, 8:16], -40., 40.)))
        n = np.tanh(gates_x[:, 16:24] + r * gates_h[:, 16:24])
        h = (1.0 - z) * n + z * h
    pred = np.clip(h @ head_w.T + head_b, -2., 2.)
    return np.column_stack((h, pred))


def _gru_weekly(x_daily, week_pos, as_of, daily_dates=None):
    """Use out-of-time checkpoint features BOTH in historical fit and inference.

    A snapshot trained through year y is eligible starting in year y+1.
    Historical weeks NEVER get re-encoded by a later trained snapshot.
    Our earliest checkpoint is trained through 2017, so 2017 has no
    demonstrably out-of-time GRU representation and its GRU coordinates
    are zero in the second-stage training design matrix.
    """
    if daily_dates is None:
        raise ValueError('GRU chronological features require daily_dates')
    dates = pd.DatetimeIndex(daily_dates)
    years = dates[week_pos].year.to_numpy(dtype=int)
    out = np.zeros((len(week_pos), 11), dtype=np.float64)
    eligible = years >= 2018
    if not np.any(eligible):
        return out
    cutoffs = (np.clip(years - 1, 2017, 2021)
               if ROLLING_GRU else np.full(len(years), 2017, dtype=int))
    # Grouped matrix inference keeps runtime bounded; each historical week's
    # checkpoint depends only on its own decision date, not on today's date.
    for cutoff in np.unique(cutoffs[eligible]):
        mask = eligible & (cutoffs == cutoff)
        out[mask] = _gru_forward_checkpoint(x_daily, week_pos[mask], cutoff)
    return out


def _weekly_indices(index):
    # Current incomplete week is included only to the extent already seen.
    periods = index.to_period("W-FRI").astype(str).to_numpy()
    return np.r_[np.flatnonzero(periods[:-1] != periods[1:]), len(index) - 1]


def _build_weekly(data):
    panel = _read_panel(data)
    if panel is None:
        return None
    qqq, spy, vix, credit, curve = panel
    x_daily, ret1, ret5, spy5, vol20, vix5 = _sequence_inputs(qqq, spy, vix)
    week_pos = _weekly_indices(qqq.index)
    dates = qqq.index[week_pos]
    n = len(week_pos)
    if n < 30:
        return None
    h = _gru_weekly(x_daily, week_pos, dates[-1], qqq.index)
    close = qqq.to_numpy(dtype=float)
    q21 = qqq / qqq.shift(21) - 1.
    spy21 = spy / spy.shift(21) - 1.
    trend = qqq / qqq.rolling(126).mean() - 1.
    vix_raw = vix.to_numpy(dtype=float)
    vix_pct = np.full(n, 0.5, dtype=float)
    for j, pos in enumerate(week_pos):
        p = vix_raw[max(0, pos - 251):pos]
        if len(p) >= 59:
            vix_pct[j] = np.mean(p < vix_raw[pos])
    vv = vol20.to_numpy()[week_pos]
    tg = np.nan_to_num(trend.to_numpy()[week_pos], nan=0.0)
    m21 = np.nan_to_num(q21.to_numpy()[week_pos], nan=0.0)
    momentum_spy = np.nan_to_num(spy21.to_numpy()[week_pos], nan=0.0)
    r5 = np.nan_to_num(ret5.to_numpy()[week_pos], nan=0.0)
    spy_r5 = np.nan_to_num(spy5.to_numpy()[week_pos], nan=0.0)
    vr5 = np.nan_to_num(vix5.to_numpy()[week_pos], nan=0.0)
    c = credit.to_numpy()[week_pos]
    y = curve.to_numpy()[week_pos]
    slow_score = np.clip(.5 + 3.0 * tg, 0., 1.)
    rebound_score = np.clip(.5 + 4.0 * m21, 0., 1.)
    trend_regime = .70 * slow_score + .30 * rebound_score
    risk_score = .75 * trend_regime + .25 * (1.0 - vix_pct)
    mul = .65 + .35 * risk_score
    rule = np.clip((TARGET_ANNUAL_VOL / np.maximum(vv, 1e-6)) * mul, .10, 1.00)
    # Use 0.5 fallback when the 126-day rule history is not yet established.
    rule[week_pos < 126] = 0.50
    # Historical Stage-2 exposure must be the learning baseline, too.
    # Shock conditions replicate the rule-only contract, strictly using
    # same-date QQQ/VIX information. This avoids training features on v0 and
    # then deploying RL relative to v1.
    panic_mask = r5 <= PANIC_QQQ_RETURN_5D
    stress_mask = ((r5 <= STRESS_QQQ_RETURN_5D)
                   & (vr5 >= STRESS_VIX_RELATIVE_RISE_5D))
    rule[panic_mask] = np.minimum(rule[panic_mask], PANIC_EXPOSURE_CAP)
    stress_mask &= ~panic_mask
    rule[stress_mask] = np.minimum(rule[stress_mask], STRESS_EXPOSURE_CAP)
    regimes = _regime_path(r5, vr5, m21, tg, vix_pct, momentum_spy)
    # Fixed-scale features avoid accidental future-fitted normalizers.
    # GRU columns above are historical out-of-time snapshots for each week.
    base = np.column_stack((h,
        2.0 * rule - 1.0,
        np.clip(r5 / .10, -2., 2.),
        np.clip(m21 / .20, -2., 2.),
        np.clip(vv / .40 - 1., -2., 2.),
        np.clip(tg / .12, -2., 2.),
        2. * vix_pct - 1.,
        np.clip(vr5 / .5, -2., 2.),
        np.clip(c / 3.0 - 1., -2., 2.),
        np.clip(y / 2., -2., 2.),
        np.clip(spy_r5 / .10, -2., 2.)))
    base = np.clip(np.nan_to_num(base), -2., 2.)
    dates = pd.DatetimeIndex(dates)
    price_week = close[week_pos]
    # Ex-post labels for the *next* completed holding week t+1. These are
    # shifted by a week before being used as features for a current decision.
    next_week_dd = np.full(n, np.nan, dtype=float)
    next_week_up = np.full(n, np.nan, dtype=float)
    for t in range(n - 1):
        path = close[week_pos[t]+1:week_pos[t+1]+1]
        if len(path) and price_week[t] > 0 and np.all(np.isfinite(path)):
            ref = float(price_week[t])
            peaks = np.maximum.accumulate(np.r_[ref, path])[1:]
            next_week_dd[t] = max(0., float(np.max(1.-path/peaks)))
            next_week_up[t] = max(0., float(np.max(path/ref-1.)))
    prev_dd = np.r_[0., np.nan_to_num(next_week_dd[:-1])]
    prev_up = np.r_[0., np.nan_to_num(next_week_up[:-1])]
    base = np.column_stack((base, np.clip(prev_dd/.15, 0., 2.),
                            np.clip(prev_up/.15, 0., 2.)))
    return dates, price_week, rule, regimes, base


def _regime_path(q5, vix5, q21, trend, pct, spy21):
    """Past-only crisis -> cooling -> confirmed recovery with asymmetric exits.

    Cooling is an INTERNAL transition state. Its legal actions are NORMAL's
    small [-10, 0, +10] percentage-point actions, so the existing public
    5-regime action IDs and action audit remain compatible.

    A fresh shock interrupts every phase. A strong reversal releases a stale
    Panic/Stress permission without waiting two additional weekly decisions.
    Large Recovery permissions require two consecutive positive/steady
    observations and disappear immediately if renewed weakness is observed.
    Recovery can be entered only once per crisis episode.
    """
    n = len(q5)
    out = np.empty(n, dtype=np.int8)
    mode = NORMAL
    cooling = False
    calm_count = 0
    cooling_age = 0
    improve_count = 0
    recovery_age = 0
    bull_count = 0

    # Fixed architecture choices; do not tune to individual crisis dates.
    CALM_CONFIRM = 2
    RECOVERY_CONFIRM = 2
    COOLING_MAX = 6
    RECOVERY_MAX = 3
    BULL_CONFIRM = 2

    for t in range(n):
        # Same fast-shock entries as the previous version, for isolation.
        panic = (q5[t] <= -.10 or
                 (q5[t] <= -.075 and vix5[t] >= .50))
        stress = ((q5[t] <= -.06 and vix5[t] >= .20) or
                  (q5[t] <= -.030 and vix5[t] >= .30) or
                  (q5[t] <= -.05 and q21[t] <= -.08))
        bullish = (q21[t] >= .055 and trend[t] >= .015 and
                   pct[t] <= .70 and q21[t] - spy21[t] >= 0.0)

        # Shock resolution is faster when both price and fear reverse.
        strong_relief = q5[t] >= .030 and vix5[t] <= .10
        quiet = q5[t] >= -.015 and vix5[t] <= .10
        # Confirming a recovery is deliberately stricter than simply being
        # less negative. A small positive week alone is not sufficient.
        recovery_evidence = (
            (q5[t] >= .010 and q21[t] >= 0.0 and vix5[t] <= .10) or
            (q5[t] >= .025 and q21[t] >= -.025 and vix5[t] <= -.10)
        )
        # An adverse week removes the large +30pp permission even if the
        # original shock entry thresholds are no longer active.
        renewed_weakness = (q5[t] <= -.025 or vix5[t] >= .20 or
                            q21[t] <= -.070)

        if panic:
            mode = PANIC
            cooling = False
            calm_count = cooling_age = improve_count = recovery_age = bull_count = 0
        elif stress:
            if mode != PANIC:
                mode = STRESS
            cooling = False
            calm_count = cooling_age = improve_count = recovery_age = bull_count = 0
        elif not ENABLE_HYSTERESIS:
            # Independent, memoryless ablation: only today's observations.
            mode = BULL if bullish else NORMAL
            cooling = False
        elif mode in (PANIC, STRESS):
            calm_count = calm_count + 1 if quiet else 0
            if strong_relief or calm_count >= CALM_CONFIRM:
                # Distinct cooling phase: safe, normal-sized actions only.
                mode = NORMAL
                cooling = True
                cooling_age = 0
                improve_count = 0
                recovery_age = 0
                bull_count = 0
                calm_count = 0
        elif cooling:
            mode = NORMAL
            cooling_age += 1
            if renewed_weakness:
                improve_count = 0
            else:
                improve_count = improve_count + 1 if recovery_evidence else 0
            if improve_count >= RECOVERY_CONFIRM:
                mode = RECOVERY
                cooling = False
                recovery_age = 0
                bull_count = 0
                improve_count = 0
            elif cooling_age >= COOLING_MAX:
                # No fresh shock => leave the recovery permission unused.
                # Do not re-open it without a *new* Stress/Panic episode.
                cooling = False
                cooling_age = 0
                improve_count = 0
        elif mode == RECOVERY:
            recovery_age += 1
            if renewed_weakness or recovery_age >= RECOVERY_MAX:
                mode = NORMAL
                recovery_age = bull_count = 0
            else:
                bull_count = bull_count + 1 if bullish else 0
                if bull_count >= BULL_CONFIRM:
                    mode = BULL
                    bull_count = recovery_age = 0
        elif mode == BULL:
            # Risk entry above still overrides immediately.
            if not bullish or renewed_weakness:
                mode = NORMAL
                bull_count = 0
        else:
            bull_count = bull_count + 1 if bullish else 0
            if bull_count >= BULL_CONFIRM:
                mode = BULL
                bull_count = 0

        out[t] = mode
    return out


def _actions(mode):
    return ACTIONS[int(mode)] if ENABLE_REGIME_GATES else NORMAL_ACTIONS



def _predictor_features(state):
    """Small fixed-scale predictor; importantly includes *trained* GRU heads.

    h[:,0:8] is the temporal state, h[:,8:11] are GRU-supervised
    price-path forecasts. Other columns are already fixed-scale indicators.
    No normalizer is fit using future observations.
    """
    s = np.asarray(state, dtype=float)
    if s.ndim == 1:
        s = s.reshape(1, -1)
    # state: 8 GRU latents, 3 supervised GRU heads, 10 indicators, 2 lags
    selected = np.column_stack((
        np.ones(s.shape[0]),
        s[:,8:11],       # GRU future min/max/close supervised outputs
        s[:,0:4],        # four recurrent temporal coordinates
        s[:,11],         # Rule exposure, [-1,1]
        s[:,12],         # last five QQQ trading-day momentum
        s[:,13],         # last 21 QQQ trading-day momentum
        s[:,14],         # realized volatility
        s[:,15],         # 126-session trend
        s[:,16],         # VIX historical percentile
        s[:,17],         # VIX five-day acceleration
        s[:,18],         # point-in-time lagged credit spread
        s[:,-2:],        # realized downside/upside in *previous* week
    ))
    return np.clip(np.nan_to_num(selected, nan=0.), -3., 3.)


def _supervised_outcomes(week_close, state, start, stop):
    """Return in percentage units; future path labels from t+1 only.

    stop is inclusive and always at most anchor-2. It is deliberately
    impossible to read labels of an unfinished holding week at inference.
    """
    idx = np.arange(start, stop+1, dtype=int)
    ret = 100.*(week_close[idx+1]/week_close[idx]-1.)
    # At t+1 the lagged feature stores the COMPLETED holding period [t,t+1].
    dd = 15.*state[idx+1, -2]
    up = 15.*state[idx+1, -1]
    y = np.column_stack((ret,dd,up))
    return idx, y


def _fit_forecaster(anchor, dates, q_close, rule, regimes, state, prior=None):
    """Regularized expanding-window fit on truly observed historical weeks.

    Predictor estimates [weekly return, intraholding downside, upside].
    The optional 2017 anchor is a shrinkage prior, not a future checkpoint.
    For each history week there is only ONE target path, never a fabricated
    collection of independent counterfactual action experiences.
    """
    start = int(np.searchsorted(dates.values, np.datetime64('2017-01-03')))
    # anchor may be an incomplete current week. The extra one-week lag is a
    # conservative availability buffer for execution and weekend timestamps.
    stop = min(anchor-2, len(dates)-3)
    if stop-start+1 < 27:
        return None
    inds, y = _supervised_outcomes(q_close, state, start, stop)
    X = _predictor_features(state[inds])
    valid = np.isfinite(y).all(axis=1) & np.isfinite(X).all(axis=1)
    X, y, inds = X[valid],y[valid],inds[valid]
    if len(X)<27:
        return None
    recency = np.exp(-math.log(2.)*(stop-inds)/FORECAST_HALF_LIFE_WEEKS)
    recency /= max(1e-9, float(np.mean(recency)))
    wx = X*np.sqrt(recency[:,None])
    wy = y*np.sqrt(recency[:,None])
    diag = np.full(X.shape[1],FORECAST_RIDGE,dtype=float)
    diag[0] = 0.2  # do not excessively bias the weekly return intercept to 0
    gram = wx.T@wx + np.diag(diag)
    rhs = wx.T@wy
    if prior is not None:
        diag_anchor = np.full(X.shape[1],FORECAST_ANCHOR_RIDGE)
        diag_anchor[0] = 0.5
        gram += np.diag(diag_anchor)
        rhs += diag_anchor[:,None]*prior
    try:
        weights = np.linalg.solve(gram,rhs)
    except np.linalg.LinAlgError:
        return None
    return weights if np.isfinite(weights).all() else None


def _score_actions(prediction, rule_exposure, previous_exposure, regime, action_sets=None):
    """Finite-action market-proxy Q utility; zero action has value exactly 0.

    Q(e)-Q(rule) uses the *forecast* of completed next-week returns and
    daily-close downside. Actions are evaluated under an exogenous-price
    approximation and subject to the regime's non-levered admissible set.
    """
    ret = float(np.clip(prediction[0], -7., 7.))/100.
    dd = float(np.clip(prediction[1], 0., 12.))/100.
    up = float(np.clip(prediction[2], 0., 12.))/100.
    b = float(np.clip(rule_exposure,0.,1.))
    prev = float(np.clip(previous_exposure,0.,1.))
    options = (_actions(regime) if action_sets is None
               else action_sets[int(regime)])
    e = np.clip(b+options,0.,1.)
    # Conservative upside participation, never encourages a bull market on
    # the basis of intraholding high prices without a positive close forecast.
    upside_edge = Q_UPSIDE_PARTICIPATION*min(up,max(0.,ret))
    growth = (e-b)*(ret+upside_edge)
    defense = Q_DOWNSIDE_AVERSION*(e*e-b*b)*dd
    tc = Q_TURNOVER_COST*(np.abs(e-prev)-abs(b-prev))
    regularizer = Q_RESIDUAL_COST*np.abs(e-b)
    advantage = 100.*(growth-defense-tc-regularizer)
    return options, advantage


# --- Fixed Stage-2 protective rule: exact formula, used as backbone ---
@dataclass(frozen=True)
class RuleFeatures:
    realized_vol: float       # Annualized volatility of past QQQ daily returns.
    trend_gap: float          # Latest QQQ close / trailing 126-session SMA - 1.
    momentum_21d: float       # QQQ last close / close 21 sessions ago - 1.
    vix_percentile: float     # Rolling percentile, relative to historical VIX values.
    qqq_return_5d: float = float("nan")  # Available 5-session QQQ total return.
    vix_relative_rise_5d: float = float("nan")  # Current / 5 sessions ago - 1.


def _clip(x: float, low: float = 0.0, high: float = 1.0) -> float:
    return float(np.clip(x, low, high))


def _build_rule_features(data) -> RuleFeatures | None:
    """Compute all features using the as-of-limited official DataView only."""
    # QQQ is used as a liquid growth-equity risk proxy; the traded portfolio
    # itself is STILL selected by the course's unmodified selection module.
    qqq_frame = data.close(["QQQ"], lookback=VIX_PERCENTILE_SESSIONS + 1)
    if "QQQ" not in qqq_frame:
        return None
    qqq = pd.to_numeric(qqq_frame["QQQ"], errors="coerce")
    qqq = qqq.replace([np.inf, -np.inf], np.nan).dropna()
    qqq = qqq[qqq > 0]
    if len(qqq) < TREND_SESSIONS:
        return None

    recent_returns = qqq.pct_change(fill_method=None).dropna().tail(REALIZED_VOL_SESSIONS)
    if len(recent_returns) < REALIZED_VOL_SESSIONS:
        return None
    realized_vol = float(recent_returns.std(ddof=1) * math.sqrt(252.0))
    if not np.isfinite(realized_vol) or realized_vol <= 0:
        return None

    last_price = float(qqq.iloc[-1])
    slow_mean = float(qqq.tail(TREND_SESSIONS).mean())
    if not np.isfinite(slow_mean) or slow_mean <= 0:
        return None
    trend_gap = last_price / slow_mean - 1.0
    momentum_21d = last_price / float(qqq.iloc[-MOMENTUM_SESSIONS - 1]) - 1.0
    qqq_return_5d = last_price / float(qqq.iloc[-SHOCK_LOOKBACK_SESSIONS - 1]) - 1.0

    vix = pd.to_numeric(data.market("^VIX"), errors="coerce")
    vix = vix.replace([np.inf, -np.inf], np.nan).dropna().tail(VIX_PERCENTILE_SESSIONS)
    vix_relative_rise_5d = float("nan")
    if len(vix) >= SHOCK_LOOKBACK_SESSIONS + 1:
        vix_past = float(vix.iloc[-SHOCK_LOOKBACK_SESSIONS - 1])
        if vix_past > 0:
            vix_relative_rise_5d = float(vix.iloc[-1] / vix_past - 1.0)
    if len(vix) >= MIN_VIX_SESSIONS:
        # Reference distribution excludes the latest point; only historical
        # observations available on the decision date are used.
        vix_percentile = float((vix.iloc[:-1] < float(vix.iloc[-1])).mean())
    else:
        # Missing VIX contributes neutral information, not a false 'calm' signal.
        vix_percentile = 0.5
    return RuleFeatures(
        realized_vol, trend_gap, momentum_21d, vix_percentile,
        qqq_return_5d, vix_relative_rise_5d,
    )


def _rule_exposure(f: RuleFeatures) -> float:
    """Continuous risk-budget rule, intentionally not yet optimized on returns."""
    # Both mappings are continuous; avoid binary 0/1 crossing of a single SMA.
    trend_score = _clip(0.5 + TREND_SCORE_SLOPE * f.trend_gap)
    rebound_score = _clip(0.5 + REBOUND_SCORE_SLOPE * f.momentum_21d)
    trend_regime = LONG_TREND_WEIGHT * trend_score + (1.0 - LONG_TREND_WEIGHT) * rebound_score

    # VIX is forward-looking *implied* volatility, distinct from realized vol.
    vix_calm = 1.0 - _clip(f.vix_percentile)
    risk_score = (1.0 - VIX_CALM_WEIGHT) * trend_regime + VIX_CALM_WEIGHT * vix_calm
    risk_multiplier = RISK_MULTIPLIER_FLOOR + (1.0 - RISK_MULTIPLIER_FLOOR) * risk_score

    # A volatility budget plus a stress multiplier. All exposures are long-only.
    scaled = (TARGET_ANNUAL_VOL / f.realized_vol) * risk_multiplier
    return _clip(scaled, MIN_EXPOSURE, MAX_EXPOSURE)


def _shock_regime(f: RuleFeatures) -> str:
    """Point-in-time signal for NEXT weekly rebalance, not intraday orders.

    Panic uses price alone, so missing/stale VIX values do not suppress
    emergency defense after a very large 5-session QQQ loss.
    Stress requires both fast drawdown and accelerating implied volatility.
    """
    if np.isfinite(f.qqq_return_5d) and f.qqq_return_5d <= PANIC_QQQ_RETURN_5D:
        return "panic"
    if (np.isfinite(f.qqq_return_5d)
            and f.qqq_return_5d <= STRESS_QQQ_RETURN_5D
            and np.isfinite(f.vix_relative_rise_5d)
            and f.vix_relative_rise_5d >= STRESS_VIX_RELATIVE_RISE_5D):
        return "stress"
    return "normal"


def _apply_shock_cap(e_rule: float, f: RuleFeatures) -> float:
    """Safety cap: only lowers the base Rule; no changes in normal regimes."""
    regime = _shock_regime(f)
    if regime == "panic":
        return min(e_rule, PANIC_EXPOSURE_CAP)
    if regime == "stress":
        return min(e_rule, STRESS_EXPOSURE_CAP)
    return e_rule






def _permission_gate(f: RuleFeatures, shock: str, weekly_state: np.ndarray,
                     week_index: int, mode: int):
    """Gate *incremental RL permissions*, never modify the fixed Rule-v1 cap.

    The early-warning mask prevents an RL add during a developing drawdown
    that has not yet crossed Rule-v1's harder emergency thresholds.
    After a recently *observed* emergency, a genuine price/fear reversal
    prevents an RL-driven extra sell while Rule v1 itself remains in control.
    Neither gate forces a trade. All data are as-of visible; no future labels.
    """
    options = list(HYBRID_ACTIONS)
    if shock != "normal":
        return options

    q5, v5 = f.qqq_return_5d, f.vix_relative_rise_5d
    if not np.isfinite(q5):
        return options
    # Leading stress permission: already a component of the preexisting
    # regime logic, but previously discarded whenever the Rule-v1 hard
    # shock cap had not yet fired. Also capture sharp price-only weakness.
    risk_watch = ((q5 <= -0.030 and np.isfinite(v5) and v5 >= 0.20)
                  or q5 <= -0.050)
    if risk_watch:
        options[mode] = options[mode][options[mode] <= 0.0]
        return options

    # Look only at *prior* decision weeks for a recent Rule-v1 hard shock.
    # The state features are qqq_5d/0.10 and vix_5d/0.50, respectively.
    start = max(0, week_index - 3)
    prior = weekly_state[start:week_index]
    if len(prior):
        prior_q5 = prior[:, 12]
        prior_v5 = prior[:, 17]
        prior_shock = ((prior_q5 <= -1.00) |
                       ((prior_q5 <= -0.60) & (prior_v5 >= 0.40)))
        recent_shock = bool(np.any(prior_shock))
    else:
        recent_shock = False
    relief = (q5 >= .030 or (np.isfinite(v5) and v5 <= -.10))
    if recent_shock and relief:
        # Do not force a rebound purchase; merely disallow an *additional*
        # learned cut after Rule-v1 already defended the shock.
        options[mode] = options[mode][options[mode] >= 0.0]
    return options


def _oof_guarded_exposure(as_of, data, _rebound_info=None, _prepared=None) -> float:
    """Stage-2 protective Rule v1 + guarded temporal rolling residual.

    The fixed Stage-2 exposure is the identity baseline when RL is disabled.
    The RL policy may lower exposure at any time, but cannot defeat the
    previously established Stress/Panic cap. No IO or mutable global updates.
    """
    f = _prepared[0] if _prepared is not None else _build_rule_features(data)
    if f is None:
        return 0.50
    rule_v1 = _apply_shock_cap(_rule_exposure(f), f)
    if not ENABLE_RL or pd.Timestamp(as_of) < RL_START:
        return float(rule_v1)

    res = _prepared[1] if _prepared is not None else _build_weekly(data)
    if res is None:
        return float(rule_v1)
    dates, q_close, rule_v1_week, regimes, state = res
    now = len(dates)-1
    first_rl = int(np.searchsorted(dates.values, RL_START.to_datetime64()))
    if first_rl < 45:
        return float(rule_v1)
    frozen = _fit_forecaster(first_rl, dates, q_close, rule_v1_week, regimes, state)
    if frozen is None:
        return float(rule_v1)
    model = frozen
    if ROLLING_Q:
        anchor = first_rl + ((now-first_rl)//UPDATE_EVERY_WEEKS)*UPDATE_EVERY_WEEKS
        update = _fit_forecaster(anchor, dates, q_close,
                                 rule_v1_week, regimes, state, prior=frozen)
        if update is not None:
            begin = int(np.searchsorted(dates.values, np.datetime64('2017-01-03')))
            observed = regimes[begin:max(begin, anchor-1)]
            n_same = int(np.count_nonzero(observed == regimes[now]))
            confidence = n_same/(n_same+REGIME_PRIOR_EQUIV_WEEKS)
            model = ((1.-FORECAST_ROLLING_BLEND*confidence)*frozen
                     + FORECAST_ROLLING_BLEND*confidence*update)
    forecast = _predictor_features(state[now]) @ model
    # Rule v1 is the decision baseline; do not score actions against Rule v0.
    mode = int(regimes[now])
    shock = _shock_regime(f)
    if shock == 'panic':
        mode = PANIC
    elif shock == 'stress':
        mode = STRESS
    elif mode in (PANIC, STRESS):
        # A latched regime without an ongoing shock is cooling, not permission
        # for a delayed oversized panic sell after the rebound has started.
        mode = NORMAL
    # Previous target is the already-known *Stage-2* historical target, not
    # an unknown future actual holding. The scorer's turnover proxy remains
    # only a proxy for the course's actual executed trades.
    previous = float(rule_v1_week[max(0, now - 1)])
    permissions = _permission_gate(f, shock, state, now, mode)
    options, advantage = _score_actions(forecast[0], float(rule_v1),
                                        previous, mode,
                                        action_sets=permissions)
    chosen = int(np.argmax(advantage))
    if advantage[chosen] <= Q_MIN_ADVANTAGE:
        chosen = int(np.argmin(np.abs(options)))
    candidate = float(np.clip(rule_v1+options[chosen], 0., 1.))
    # Critical invariant: even a flawed learned policy cannot raise the
    # portfolio through the existing fixed emergency exposure ceiling.
    if shock == 'panic':
        candidate = min(candidate, PANIC_EXPOSURE_CAP)
    elif shock == 'stress':
        candidate = min(candidate, STRESS_EXPOSURE_CAP)
    if _rebound_info is not None:
        # These are features observed strictly before the current decision.
        # Use the same prior-week hard-shock definition as _permission_gate().
        prior = state[max(0, now - 3):now]
        recent_shock = False
        if len(prior):
            recent_shock = bool(np.any(
                (prior[:, 12] <= -1.0) |
                ((prior[:, 12] <= -0.60) & (prior[:, 17] >= 0.40))
            ))
        _rebound_info['effective_mode'] = int(mode)
        _rebound_info['recent_hard_shock'] = recent_shock
    return float(candidate)


# ===== RESEARCH CANDIDATE: FROZEN, LEARNED RULE-v1 RESIDUAL Q =====
# Annual offline contextual-bandit advantage coefficients, generated by train_timing.py.
# Selection-only NAV close-to-close paths are a counterfactual reward proxy,
# not exact execution simulation or multi-step Bellman reinforcement learning.
USE_FROZEN_DIRECT_Q = True
DIRECT_Q_ACTIVATION = pd.Timestamp('2019-01-01')
DIRECT_Q_RIDGE = 24.0
DIRECT_Q_THRESHOLD_PP = 0.035
DIRECT_Q_FEATURE_IDX = (0, 1, 2, 3, 4, 5, 6, 13, 14)
